import { useMemo } from 'react';
import { 
  applySegmentFilter, 
  applyClassFilter, 
  applyDirectFilter 
} from '../utils/flightFilters';

const useFilteredFlights = (
  flightData,
  segmentFilter,
  classFilter,
  directFilter,
  sourceFilter,
  airlinesFilter,
  pointsFilter
) => {
  return useMemo(() => {
    if (!flightData?.rawData) return [];

    let filtered = [...flightData.rawData];

    // Apply segment filter
    filtered = applySegmentFilter(filtered, segmentFilter);

    // Apply class filter
    filtered = applyClassFilter(filtered, classFilter);

    // Apply direct filter
    filtered = applyDirectFilter(filtered, directFilter, classFilter);

    // Apply source filter
    if (sourceFilter.sources.length > 0) {
      filtered = filtered.filter(flight => {
        const isInFilter = sourceFilter.sources.includes(flight.source);
        return sourceFilter.mode === 'include' ? isInFilter : !isInFilter;
      });
    }

    // Apply airlines filter
    if (airlinesFilter.airlines.length > 0) {
      filtered = filtered.filter(flight => {
        const classes = classFilter.length > 0 ? classFilter : ['Y', 'W', 'J', 'F'];
        return classes.some(classCode => {
          const airlines = flight[`${classCode}Airlines`] || '';
          return airlinesFilter.airlines.some(airline => 
            airlines.includes(airline)
          );
        });
      });
    }

    // Apply points filter
    if (pointsFilter) {
      filtered = filtered.filter(flight => {
        const classes = classFilter.length > 0 ? classFilter : ['Y', 'W', 'J', 'F'];
        return classes.some(classCode => {
          const points = Number(flight[`${classCode}MileageCost`] || 0);
          return points >= pointsFilter[0] && points <= pointsFilter[1];
        });
      });
    }

    return filtered;
  }, [
    flightData, 
    segmentFilter, 
    classFilter, 
    directFilter, 
    sourceFilter, 
    airlinesFilter,
    pointsFilter
  ]);
};

export default useFilteredFlights;
